import ast
import unittest

import docscheck as D

PATH = "seedbank/inventory.py"
ORIGINAL = {"remove_lot": "FunctionDef(name='remove_lot', args=arguments(posonlyargs=[], args=[arg(arg='stock'), arg(arg='sku'), arg(arg='qty')], kwonlyargs=[], kw_defaults=[], defaults=[]), body=[Assign(targets=[Name(id='have', ctx=Store())], value=Call(func=Attribute(value=Name(id='stock', ctx=Load()), attr='get', ctx=Load()), args=[Name(id='sku', ctx=Load()), Constant(value=0)], keywords=[])), If(test=BoolOp(op=Or(), values=[Compare(left=Name(id='qty', ctx=Load()), ops=[LtE()], comparators=[Constant(value=0)]), Compare(left=Name(id='qty', ctx=Load()), ops=[Gt()], comparators=[Name(id='have', ctx=Load())])]), body=[Raise(exc=Call(func=Name(id='ValueError', ctx=Load()), args=[BinOp(left=Constant(value='cannot remove %d of %s (have %d)'), op=Mod(), right=Tuple(elts=[Name(id='qty', ctx=Load()), Name(id='sku', ctx=Load()), Name(id='have', ctx=Load())], ctx=Load()))], keywords=[]))], orelse=[]), Assign(targets=[Subscript(value=Name(id='stock', ctx=Load()), slice=Name(id='sku', ctx=Load()), ctx=Store())], value=BinOp(left=Name(id='have', ctx=Load()), op=Sub(), right=Name(id='qty', ctx=Load()))), If(test=Compare(left=Subscript(value=Name(id='stock', ctx=Load()), slice=Name(id='sku', ctx=Load()), ctx=Load()), ops=[Eq()], comparators=[Constant(value=0)]), body=[Delete(targets=[Subscript(value=Name(id='stock', ctx=Load()), slice=Name(id='sku', ctx=Load()), ctx=Del())])], orelse=[]), Return(value=BinOp(left=Name(id='have', ctx=Load()), op=Sub(), right=Name(id='qty', ctx=Load())))], decorator_list=[])"}


class DocstringTests(unittest.TestCase):
    def setUp(self):
        self.tree = D.parse(PATH)

    def test_code_is_unchanged(self):
        now = {n.name: D.stripped_dump(n) for n in self.tree.body if isinstance(n, ast.FunctionDef)}
        self.assertEqual(now, ORIGINAL, "only docstrings may change")

    def test_module_docstring(self):
        self.assertTrue((ast.get_docstring(self.tree) or "").strip(), "the module needs a docstring")

    def test_every_public_function_matches_the_style(self):
        problems = []
        for fn in D.public_functions(self.tree):
            doc = ast.get_docstring(fn)
            if not doc:
                problems.append("%s: no docstring" % fn.name)
                continue
            info = D.sections(doc)
            parsed = info["parsed"]
            if not info["summary"].endswith("."):
                problems.append("%s: the summary line should end with a period" % fn.name)
            want_args = set(D.params(fn))
            got_args = set(parsed.get("Args", {}))
            if want_args != got_args:
                problems.append("%s: Args documents %s but the parameters are %s" % (fn.name, sorted(got_args), sorted(want_args)))
            for name, text in parsed.get("Args", {}).items():
                if D.words(text) < 2:
                    problems.append("%s: the description of %s is too short" % (fn.name, name))
            if D.returns_value(fn) != ("Returns" in parsed):
                problems.append("%s: Returns must be present exactly when the function returns a value" % fn.name)
            elif "Returns" in parsed and D.words(parsed["Returns"]) < 2:
                problems.append("%s: the Returns description is too short" % fn.name)
            want_raises = D.explicit_raises(fn)
            got_raises = set(parsed.get("Raises", {}))
            if want_raises != got_raises:
                problems.append("%s: Raises lists %s but the function raises %s" % (fn.name, sorted(got_raises), sorted(want_raises)))
            for name, text in parsed.get("Raises", {}).items():
                if D.words(text) < 2:
                    problems.append("%s: the description of %s is too short" % (fn.name, name))
        self.assertFalse(problems, "\n".join(problems))

